          link.classList.add(
            'bg-primary-container',
            'text-on-primary-container',
            'font-headline-sm',
            'text-headline-sm',
            'rounded-xl'
          );
          link.classList.remove(
            'text-on-surface-variant',
            'hover:bg-sage-soft',
            'font-body-md',
            'text-body-md'
          );
        } else {
          link.classList.remove(
            'bg-primary-container',
            'text-on-primary-container',
            'font-headline-sm',
            'text-headline-sm'
          );
        }
