<!-- Toast Notification Container -->
<div class="fixed bottom-6 right-6 z-50 transform translate-y-24 opacity-0 transition-all duration-300 pointer-events-none flex items-center gap-space-sm px-space-md py-3 rounded-xl bg-on-surface text-surface shadow-2xl" id="toastMessage">
<span class="material-symbols-outlined text-success text-[20px]" id="toastIcon">check_circle</span>
<span class="font-body-sm text-body-sm font-semibold" id="toastText">Action updated</span>
</div>
<!-- Client-side Interactive Logic -->
<script>
    function showToast(message, icon = 'check_circle') {
      const toast = document.getElementById('toastMessage');
      const text = document.getElementById('toastText');
      const iconEl = document.getElementById('toastIcon');
      text.textContent = message;
      iconEl.textContent = icon;
      toast.classList.remove('translate-y-24', 'opacity-0');
      toast.classList.add('translate-y-0', 'opacity-100');
      setTimeout(() => {
        toast.classList.remove('translate-y-0', 'opacity-100');
        toast.classList.add('translate-y-24', 'opacity-0');
      }, 3500);
    }

    function openInviteModal() {
      document.getElementById('inviteModal').classList.remove('hidden');
    }

    function closeInviteModal() {
      document.getElementById('inviteModal').classList.add('hidden');
    }

    function handleInviteSubmit(e) {
      e.preventDefault();
      const name = document.getElementById('inviteName').value;
      const contact = document.getElementById('inviteContact').value;
      closeInviteModal();
      showToast(`Magic invitation sent to ${name} (${contact})`, 'send');
      e.target.reset();
    }

    function openEditRoleModal(name, role) {
      document.getElementById('editTargetName').textContent = `Member: ${name}`;
      document.getElementById('editRoleSelect').value = role;
      document.getElementById('editRoleModal').classList.remove('hidden');
      closeAllCardMenus();
    }

    function closeEditRoleModal() {
      document.getElementById('editRoleModal').classList.add('hidden');
    }

    function saveEditRoleModal() {
      const role = document.getElementById('editRoleSelect').value;
      closeEditRoleModal();
      showToast(`Updated member privileges to "${role}"`);
    }

    function removeMemberMock() {
      if (
        confirm(
          'Are you sure you want to revoke this seat? Their devices will lose geofence sync.'
        )
      ) {
        closeEditRoleModal();
        showToast('Member removed from household circle.', 'delete');
      }
    }

    function openRolesMatrixModal() {
      const section = document.querySelector('table');
      if (section) {
        section.scrollIntoView({ behavior: 'smooth', block: 'center' });
        showToast('Viewing full household permissions matrix below', 'policy');
      }
    }

    function resendInviteNotification(btn) {
      btn.innerHTML = `<span class="material-symbols-outlined text-[16px] animate-spin">refresh</span><span>Sending...</span>`;
      btn.disabled = true;
      setTimeout(() => {
        btn.innerHTML = `<span class="material-symbols-outlined text-[16px] text-success">done</span><span>Sent!</span>`;
        showToast('Invitation link re-dispatched to Uncle Dave.', 'mark_email_read');
        setTimeout(() => {
          btn.innerHTML = `<span class="material-symbols-outlined text-[16px]">forward_to_inbox</span><span>Resend Invite</span>`;
          btn.disabled = false;
        }, 3000);
      }, 800);
    }

    function revokeInviteNotification() {
      if (confirm('Revoke pending invite for Uncle Dave? The open seat will be freed up.')) {
        const card = document.getElementById('pendingInviteCard');
        if (card) {
          card.style.opacity = '0.4';
          card.style.pointerEvents = 'none';
          showToast('Invitation revoked. 1 open seat restored.', 'check_circle');
        }
      }
    }

    function toggleCardMenu(menuId) {
      const target = document.getElementById(menuId);
      const isHidden = target.classList.contains('hidden');
      closeAllCardMenus();
      if (isHidden) {
        target.classList.remove('hidden');
      }
    }

    function closeAllCardMenus() {
      document
        .querySelectorAll('[id^="menu-"]')
        .forEach((menu) => menu.classList.add('hidden'));
    }

    document.addEventListener('click', function (e) {
      if (
        !e.target.closest('[id^="menu-"]') &&
        !e.target.closest('button[onclick^="toggleCardMenu"]')
      ) {
        closeAllCardMenus();
      }
    });

    function filterMembers(type, btn) {
      document.querySelectorAll('.role-filter-pill').forEach((pill) => {
        pill.classList.remove('bg-secondary', 'text-on-secondary');
        pill.classList.add('bg-surface', 'text-on-surface-variant');
      });
      btn.classList.add('bg-secondary', 'text-on-secondary');
      btn.classList.remove('bg-surface', 'text-on-surface-variant');

      const cards = document.querySelectorAll('.member-card');
      const pendingSection = document.getElementById('pendingSection');

      if (type === 'all') {
        cards.forEach((c) => (c.style.display = 'flex'));
        if (pendingSection) pendingSection.style.display = 'flex';
      } else if (type === 'pending') {
        cards.forEach((c) => (c.style.display = 'none'));
        if (pendingSection) {
          pendingSection.style.display = 'flex';
          pendingSection.scrollIntoView({ behavior: 'smooth' });
        }
      } else {
        if (pendingSection) pendingSection.style.display = 'none';
        cards.forEach((c) => {
          if (c.getAttribute('data-role') === type) {
            c.style.display = 'flex';
          } else {
            c.style.display = 'none';
          }
        });
      }
    }

    function handleSearch(term) {
      const query = term.toLowerCase().trim();
      const cards = document.querySelectorAll('.member-card');
      cards.forEach((card) => {
        const nameData = card.getAttribute('data-name') || '';
        if (nameData.includes(query)) {
          card.style.display = 'flex';
        } else {
          card.style.display = 'none';
        }
      });
    }
  </script>
</div></main></div></body></html>